def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start time to ensure we process them in order
    # sorted() creates a new list, satisfying the non-mutation requirement
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []
    for current in sorted_intervals:
        # If merged is empty or current interval does not overlap/touch the last one
        if not merged or current[0] > merged[-1][1]:
            # Append a copy to ensure we don't mutate the original sub-lists
            merged.append(list(current))
        else:
            # There is an overlap or they touch, merge them by updating the end
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged

package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

package cache

import (
	"container/list"
	"sync"
)

// entry holds the key-value pair in the doubly linked list.
// The key is stored to facilitate removal from the map during eviction.
type entry struct {
	key   string
	value int
}

// LRU represents a fixed-capacity Least Recently Used cache.
type LRU struct {
	capacity int
	cache    map[string]*list.Element
	list     *list.List
	mu       sync.Mutex
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		cache:    make(map[string]*list.Element),
		list:     list.New(),
	}
}

// Get retrieves a value from the cache. 
// If the key exists, it moves the entry to the front (most recently used).
func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if element, ok := c.cache[key]; ok {
		c.list.MoveToFront(element)
		e := element.Value.(*entry)
		return e.value, true
	}
	return 0, false
}

// Put inserts or updates a key-value pair in the cache.
// If the key exists, it updates the value and moves it to the front.
// If the key is new and the cache is full, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.capacity <= 0 {
		return
	}

	// Update existing key
	if element, ok := c.cache[key]; ok {
		c.list.MoveToFront(element)
		e := element.Value.(*entry)
		e.value = value
		return
	}

	// Evict if at capacity
	if c.list.Len() >= c.capacity {
		last := c.list.Back()
		if last != nil {
			c.list.Remove(last)
			e := last.Value.(*entry)
			delete(c.cache, e.key)
		}
	}

	// Insert new key
	newEntry := &entry{key: key, value: value}
	element := c.list.PushFront(newEntry)
	c.cache[key] = element
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.list.Len()
}

