package router

type Route struct {
	Prefix  string
	Handler string
	Enabled bool
}

// Resolve returns the handler for the most specific enabled prefix.
func Resolve(routes []Route, path string) (string, bool) {
	var bestHandler string
	maxLen := -1
	found := false

	for _, route := range routes {
		if !route.Enabled {
			continue
		}

		if len(route.Prefix) <= len(path) && path[:len(route.Prefix)] == route.Prefix {
			// Check for path boundaries:
			// 1. Exact match (e.g., /api == /api)
			// 2. Prefix followed by a slash (e.g., /api matches /api/admin)
			// 3. Prefix ends with a slash (e.g., /api/ matches /api/admin)
			isBoundary := len(route.Prefix) == len(path) ||
				(len(route.Prefix) < len(path) && path[len(route.Prefix)] == '/') ||
					(len(route.Prefix) > 0 && route.Prefix[len(route.Prefix)-1] == '/'))

			if isBoundary {
				if len(route.Prefix) > maxLen {
					maxLen = len(route.Prefix)
					bestHandler = route.Handler
					found = true
				}
			}
		}
	}

	return bestHandler, found
}

