package retry

import "errors"

type Store interface {
	Get(key string) (string, error)
	Put(key, value string) error
}

var ErrTemporary = errors.New("temporary")
var ErrMissing = errors.New("missing")

// Ensure reads key and writes fallback only when the key is missing.
func Ensure(store Store, key, fallback string) (string, error) {
	var lastErr error
	for i := 0; i < 3; i++ {
		value, err := store.Get(key)
		if err == nil {
			return value, nil
		}
		if err == ErrMissing {
			if putErr := store.Put(key, fallback); putErr == nil {
				return fallback, nil
			}
			return "", ErrMissing
		}
		if err == ErrTemporary {
			lastErr = err
			continue
		}
		return "", err
	}
	return "", lastErr
}

package cache

import (
	"container/list"
	"sync"
)

// entry holds the data stored in the LRU cache.
type entry struct {
	key   string
	value int
}

// LRU represents a fixed-capacity Least Recently Used cache.
type LRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
	mu        sync.Mutex
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get retrieves a value from the cache by key.
// It moves the accessed item to the front of the LRU list.
func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if element, ok := c.items[key]; ok {
		c.evictList.MoveToFront(element)
		return element.Value.(*entry).value, true
	}
	return 0, false
}

// Put inserts or updates a key-value pair in the cache.
// If the key exists, it updates the value and moves it to the front.
// If the key is new and the cache is full, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.capacity <= 0 {
		return
	}

	if element, ok := c.items[key]; ok {
		c.evictList.MoveToFront(element)
		element.Value.(*entry).value = value
		return
	}

	if c.evictList.Len() >= c.capacity {
		if last := c.evictList.Back(); last != nil {
			c.evictList.Remove(last)
			kv := last.Value.(*entry)
			delete(c.items, kv.key)
		}
	}

	newEntry := &entry{key: key, value: value}
	element := c.evictList.PushFront(newEntry)
	c.items[key] = element
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return len(c.items)
}

